import {APPLIANCES,INTEREST,newCommunitySession,advanceCommunity,communityMenu,completedCommunityRecord,validateCommunityRecord} from './community-core.js';
const KEY='aimenergy.community.v1',MAX=200;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let ctx,session=null,records=[],message='',memoryOnly=false,removed=null;
const ids=()=>ctx.getSites().map(s=>String(s.id)).filter(id=>/^\d{1,12}$/.test(id));
const name=id=>ctx.getSites().find(s=>String(s.id)===String(id))?.name||id;
const newId=()=>crypto.randomUUID();
function save(){try{localStorage.setItem(KEY,JSON.stringify(records));memoryOnly=false;}catch{memoryOnly=true;message='Storage unavailable or full. Responses remain in memory; export them before leaving.';}}
function redraw(){ctx.render();}
function download(data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='AimEnergy-community-simulation.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function getCommunityEvidence(siteId){const matching=records.filter(r=>r.villageId===String(siteId));return {channel:'ussd_simulator',method:'demonstration',records:matching.map(r=>({...r,appliances:[...r.appliances]})),responses:matching.length,reviewed:matching.filter(r=>r.reviewedAt).length,scope:'Simulation sessions, not unique respondents. Review does not verify answers. No automatic scenario changes or cloud synchronization.'};}
export function initCommunityLab(options){ctx=options;try{const raw=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(raw)||raw.length>MAX)throw new Error('Invalid storage');let discarded=0;const seen=new Set();records=raw.flatMap(r=>{try{const c=validateCommunityRecord(r,ids());if(seen.has(c.id))throw new Error();seen.add(c.id);return[c];}catch{discarded++;return[];}});if(discarded)message=discarded+' invalid saved responses were skipped.';}catch{memoryOnly=true;message='Saved community responses could not be read. New responses can be exported.';}
  document.addEventListener('submit',e=>{if(e.target.id!=='community-form')return;e.preventDefault();submit();});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-community]');if(b)action(b.dataset.community,b.dataset.id);});
}
function answerSummary(a){return '<dl class="community-answer"><dt>Village</dt><dd>'+esc(a.villageId?name(a.villageId):'Not answered')+'</dd><dt>Category</dt><dd>'+esc(a.kind||'Not answered')+'</dd><dt>Appliances ('+esc(a.applianceBasis||'basis not answered')+')</dt><dd>'+esc(a.appliances?.map(x=>APPLIANCES[x]).join(', ')||'None / not answered')+'</dd>'+(a.kind==='business'?'<dt>Business operating hours</dt><dd>'+esc(a.businessHours??'Not answered')+' hours/day</dd>':'')+'<dt>Connection interest</dt><dd>'+esc(INTEREST[a.interest]||'Not answered')+'</dd></dl>';}
function submit(){try{if(!session)throw new Error('Start a preview session first.');const input=document.querySelector('#community-input');const next=advanceCommunity(session,input.value,ids());if(next.status==='complete'){if(records.length>=MAX)throw new Error('This browser has 200 responses. Export and remove a response before saving another.');const r=validateCommunityRecord(completedCommunityRecord(next),ids());records.unshift(r);session=next;message='Simulation saved for review. It has not changed the planner.';save();}else{session=next;message='';}redraw();document.querySelector('#community-input')?.focus();}catch(e){message=e.message;redraw();document.querySelector('#community-input')?.focus();}}
function action(action,id){message='';if(action==='start'){session=newCommunitySession(newId());}
  if(action==='code'){if(session?.step==='village'){document.querySelector('#community-input').value=String(ctx.getSite().id);return;}}
  if(action==='review'){const r=records.find(r=>r.id===id);if(r){r.reviewedAt=r.reviewedAt?null:new Date().toISOString();save();message='Review status updated. This remains a simulation response.';}}
  if(action==='remove'){const index=records.findIndex(r=>r.id===id);if(index>=0){removed={record:records[index],index};records.splice(index,1);save();message='Response removed. Undo is available until the next removal or page reload.';}}
  if(action==='undo'&&removed&&records.length<MAX){records.splice(removed.index,0,removed.record);removed=null;save();}
  if(action==='export')download({schema:1,exportedAt:new Date().toISOString(),channel:'ussd_simulator',method:'demonstration',scope:'Local simulation only. Not real telecom traffic, unique respondents or measured demand.',records});
  if(action==='field'){ctx.onField(id);return;}
  redraw();
}
export function renderCommunityPassport(siteId){const e=getCommunityEvidence(siteId);return '<section class="community-passport"><span class="head-tag">SIMULATION · REPORTED ANSWERS</span><h3>Community response inbox</h3><p>'+e.responses+' completed preview sessions for this village · '+e.reviewed+' reviewed. These are demonstration inputs, not real community measurements. Review does not change their evidence type.</p>'+ (e.responses?'<details><summary>Inspect simulation responses</summary>'+e.records.map(r=>'<article><span class="head-tag">'+(r.reviewedAt?'Reviewed simulation':'Pending simulation')+'</span>'+answerSummary(r)+'</article>').join('')+'</details>':'')+'<button class="btn" data-action="nav" data-view="community">Open USSD preview & review</button><p class="control-help">Appliances, operating hours and interest are kept outside forecast inputs. A field team must independently verify any real observation before making a scenario revision.</p></section>';}
export function renderCommunityLab(){const site=ctx.getSite(),current=getCommunityEvidence(site.id);return '<div class="view-heading"><h2>A voice from every kind of phone.</h2><p>Preview a basic-phone survey, review its answers and keep the source visible.</p></div><div class="info-note"><strong>USSD simulator — no live service code.</strong> This preview runs in your browser, including offline after preparation. Real USSD requires mobile coverage, a telecom provider and an online backend. No phone numbers, SMS or network sessions are collected or sent.</div><div class="community-layout"><section class="community-phone" aria-label="USSD phone simulator"><div class="community-phone-label">AimEnergy / USSD preview</div><pre class="community-screen" aria-live="polite">'+esc(session?communityMenu(session):'Basic phone. Clear questions.\n\nStart a simulated session.\nThis does not dial a real code.')+'</pre>'+(session?.status==='active'?'<form id="community-form"><label for="community-input">Your reply</label><div class="community-reply"><input id="community-input" autocomplete="off" maxlength="40" placeholder="Enter a choice" aria-describedby="community-message"><button class="btn lime" type="submit">Send reply</button></div></form>':'<button class="btn lime" data-community="start">'+(session?'Start another preview':'Start preview session')+'</button>')+'<p class="community-phone-note">00 cancels · Active previews expire after 5 minutes of inactivity. Incomplete sessions are not saved on reload.</p></section><section class="panel community-context"><span class="head-tag">'+esc(site.name)+'</span><h3>Use this village in the preview</h3><p class="community-code">'+esc(site.id)+'</p><p>Enter this code at the village prompt.'+(!ids().includes(String(site.id))?' Manual locations need an assigned numeric code before this preview can use them.':'')+'</p>'+(session?.step==='village'&&session?.status==='active'&&ids().includes(String(site.id))?'<button class="btn" data-community="code">Fill selected village code</button>':'')+'<h3>Answers so far</h3>'+answerSummary(session?.answers||{})+'<p class="control-help">Business hours are opening hours, not equivalent appliance full-power hours. Interest is not uptake, and appliance ownership does not establish measured kWh.</p></section></div><p id="community-message" role="status" class="community-message">'+esc(message)+'</p><section class="panel source-list"><div class="panel-head"><div><h2>Review inbox</h2><p class="subtext">'+records.length+' local simulation sessions · '+current.responses+' for '+esc(site.name)+' · '+(memoryOnly?'memory only':'saved in this browser')+'</p></div><button class="btn" data-community="export">Export simulation responses</button></div><div class="community-inbox">'+(records.length?records.map(r=>'<article class="community-record"><div><span class="head-tag">SIMULATION · '+(r.reviewedAt?'REVIEWED':'PENDING REVIEW')+'</span><h3>'+esc(name(r.villageId))+' / '+esc(r.kind)+'</h3><p>'+esc(r.applianceBasis)+': '+esc(r.appliances.map(x=>APPLIANCES[x]).join(', ')||'No appliances selected')+(r.kind==='business'?' · '+r.businessHours+' business hours/day':'')+' · '+esc(INTEREST[r.interest])+'</p><p class="control-help">Recorded '+esc(new Date(r.createdAt).toLocaleString())+' · No real respondent identity collected.</p></div><div class="community-record-actions"><button class="btn" data-community="review" data-id="'+esc(r.id)+'">'+(r.reviewedAt?'Return to pending':'Mark reviewed')+'</button><button class="btn" data-community="field" data-id="'+esc(r.villageId)+'">View village passport</button><button class="btn" data-community="remove" data-id="'+esc(r.id)+'">Remove</button></div></article>').join(''):'<div class="remote-empty"><h3>No completed responses yet.</h3><p>Finish and confirm a preview session. The response will appear here and in its village evidence passport.</p></div>')+(removed?'<button class="btn" data-community="undo">Undo last removal</button>':'')+'</div></section><section class="community-access"><h3>One workflow, three access modes</h3><p><strong>Web dashboard:</strong> developer planning. <strong>Offline field kit:</strong> prepared smartphone/laptop assessments. <strong>USSD:</strong> proposed basic-phone participation where mobile coverage exists.</p><p>Completed simulations stay on this device until exported. There is no automatic synchronization, deduplication of people, live provider integration or model training from these answers.</p></section>';}
